#include "unity.h"
#include "header.h"
#include "helpers.h"

void setUp(void) { }
void tearDown(void) { }

void unit_test_compileFromAST_alternation_wrapper_path(void) {
    // Setup: Build AST for alternation, e.g., regex "a|b"
    struct ASTNode* left = createNode('a');
    TEST_ASSERT_NOT_NULL(left);
    left->left = NULL;
    left->right = NULL;

    struct ASTNode* right = createNode('b');
    TEST_ASSERT_NOT_NULL(right);
    right->left = NULL;
    right->right = NULL;

    struct ASTNode* root = createNode('|');
    TEST_ASSERT_NOT_NULL(root);
    root->left = left;
    root->right = right;

    // Test: compileFromAST should take the alternation path and return a wrapper NFA
    struct NFA* nfa = compileFromAST(root);
    TEST_ASSERT_NOT_NULL(nfa);

    // The wrapperFlag should be set to 1 for the alternation wrapper
    TEST_ASSERT_EQUAL_INT(1, nfa->wrapperFlag);

    // The stateCount should be 2 for the wrapper
    TEST_ASSERT_EQUAL_INT(2, nfa->stateCount);

    // The subCount should be 2 (left and right sub-NFAs)
    TEST_ASSERT_EQUAL_INT(2, nfa->subCount);

    // The statePool and subs pointers should not be NULL
    TEST_ASSERT_NOT_NULL(nfa->statePool);
    TEST_ASSERT_NOT_NULL(nfa->subs);

    // The rulePool and currentStates pointers should not be NULL
    TEST_ASSERT_NOT_NULL(nfa->rulePool);
    TEST_ASSERT_NOT_NULL(nfa->currentStates);

    // Optionally, check that the sub NFAs are not NULL
    TEST_ASSERT_NOT_NULL(nfa->subs[0]);
    TEST_ASSERT_NOT_NULL(nfa->subs[1]);

    // Optionally, check that the statePool[0] and statePool[1] are not NULL
    TEST_ASSERT_NOT_NULL(nfa->statePool[0]);
    TEST_ASSERT_NOT_NULL(nfa->statePool[1]);

    // Cleanup
    destroyNFA(nfa);
    destroyNode(root);
}

int main(void) {
    UNITY_BEGIN();
    RUN_TEST(unit_test_compileFromAST_alternation_wrapper_path);
    return UNITY_END();
}


