    // Setup: Build AST for alternation, e.g., regex "a|b"
    struct ASTNode* left = createNode('a');
    TEST_ASSERT_NOT_NULL(left);
    left->left = NULL;
    left->right = NULL;

    struct ASTNode* right = createNode('b');
    TEST_ASSERT_NOT_NULL(right);
    right->left = NULL;
    right->right = NULL;

    struct ASTNode* root = createNode('|');
    TEST_ASSERT_NOT_NULL(root);
    root->left = left;
    root->right = right;

