    struct NFA* nfa = compileFromAST(root);
    TEST_ASSERT_NOT_NULL(nfa);

    // The wrapperFlag should be set to 1 for the alternation wrapper
    TEST_ASSERT_EQUAL_INT(1, nfa->wrapperFlag);

    // The stateCount should be 2 for the wrapper
    TEST_ASSERT_EQUAL_INT(2, nfa->stateCount);

    // The subCount should be 2 (left and right sub-NFAs)
    TEST_ASSERT_EQUAL_INT(2, nfa->subCount);

